package com.rpb.reservation.workforce;
import static com.rpb.reservation.workforce.payroll.PayrollDtos.*;
import static org.assertj.core.api.Assertions.*;
import java.util.*;import java.time.*;
import org.junit.jupiter.api.Test;
class WorkforcePayChangeImpactPostgresTest extends WorkforcePayrollPostgresTest {
 com.rpb.reservation.workforce.payroll.governance.PayChangeService changes(){var json=new com.rpb.reservation.workforce.application.WorkforceJson(new com.fasterxml.jackson.databind.ObjectMapper().findAndRegisterModules());var r=new com.rpb.reservation.workforce.payroll.governance.PayChangeRepository(jdbc,json);var pubs=new com.rpb.reservation.workforce.payroll.governance.TemplatePublicationRepository(jdbc,json);return proxy(new com.rpb.reservation.workforce.payroll.governance.PayChangeService(access,new com.rpb.reservation.workforce.payroll.PayrollAccess(access,directory,jdbc),r,configs,pubs,repository,new com.rpb.reservation.workforce.application.WorkforceAudit(logs,new com.fasterxml.jackson.databind.ObjectMapper().findAndRegisterModules()),new com.rpb.reservation.workforce.payroll.governance.PayChangeDrafts(r,configs,pubs,repository,time),time));}
 com.rpb.reservation.workforce.payroll.governance.PayChangeDtos.Request request(){var p=configs.findProfile(tenant,profile).orElseThrow();var c=new ProfileWrite(p.version(),company,employee,p.effectiveFrom(),template,new Rule("hourly","200.00","8","44",false,"1.5",List.of()),p.cpf());return changes().save(admin,store,UUID.randomUUID(),new com.rpb.reservation.workforce.payroll.governance.PayChangeDtos.Write(0L,company,employee,p.effectiveFrom(),null,c,List.of(),null,"raise"));}
 com.rpb.reservation.workforce.payroll.governance.PayChangeImpactService impactService(){var json=new com.rpb.reservation.workforce.application.WorkforceJson(new com.fasterxml.jackson.databind.ObjectMapper().findAndRegisterModules());var repo=new com.rpb.reservation.workforce.payroll.governance.PayChangeRepository(jdbc,json);var pubs=new com.rpb.reservation.workforce.payroll.governance.TemplatePublicationRepository(jdbc,json);return proxy(new com.rpb.reservation.workforce.payroll.governance.PayChangeImpactService(changes(),repo,new com.rpb.reservation.workforce.payroll.governance.PayChangeDrafts(repo,configs,pubs,repository,time),sources,new com.rpb.reservation.workforce.payroll.PayrollCalculationService(time),new com.rpb.reservation.workforce.payroll.PayrollAccess(access,directory,jdbc),payRepository,time));}
 @Test void previewUsesExistingCalculatorAndDoesNotWriteBatchOrCache(){completed();var r=request();var service=impactService();var impact=service.preview(admin,store,r.id(),"2026-10");assertThat(impact.beforeNet()).isEqualTo("640.00");assertThat(impact.afterNet()).isEqualTo("1280.00");assertThat(impact.netDifference()).isEqualTo("640.00");assertThat(jdbc.queryForObject("select count(*) from workforce_pay_batches where tenant_id=?",Integer.class,tenant)).isZero();assertThat(configs.findProfile(tenant,profile).orElseThrow().rule().rate()).isEqualTo("100.00");}
 @Test void unknownImpactIsNullRatherThanZero(){var r=request();var impact=impactService().preview(admin,store,r.id(),"2026-10");assertThat(impact.beforeNet()).isNull();assertThat(impact.afterNet()).isNull();assertThat(impact.netDifference()).isNull();assertThat(impact.issues()).contains("NO_SOURCES_REVIEW");}
 @Test void futureHourlyReviewedUnitsCannotTurnMissingWorkIntoKnownZero(){var r=request();r=changes().save(admin,store,r.id(),new com.rpb.reservation.workforce.payroll.governance.PayChangeDtos.Write(r.revision(),company,employee,r.effectiveDate(),null,null,List.of(new com.rpb.reservation.workforce.payroll.governance.PayChangeDtos.MonthWrite("2026-12",new InputWrite(0L,null,null,true,true,List.of(new Item("allowance","ow_allowance","100")),"assumed future work"))),null,"future"));var impact=impactService().preview(admin,store,r.id(),"2026-12");assertThat(impact.afterNet()).isNull();assertThat(impact.netDifference()).isNull();assertThat(impact.issues()).contains("FUTURE_ATTENDANCE_SOURCES_INCOMPLETE");assertThat(jdbc.queryForObject("select count(*) from workforce_pay_batches where tenant_id=?",Integer.class,tenant)).isZero();}
 @Test void fixedFutureEstimateRetainsExplicitEmploymentContractAssumption(){var p=configs.findProfile(tenant,profile).orElseThrow();var fixed=new Rule("monthly","3000","8","44",false,"1.5",List.of(),new Generation("fixed",List.of()));var c=new ProfileWrite(p.version(),company,employee,p.effectiveFrom(),template,fixed,p.cpf());var r=changes().save(admin,store,UUID.randomUUID(),new com.rpb.reservation.workforce.payroll.governance.PayChangeDtos.Write(0L,company,employee,p.effectiveFrom(),null,c,List.of(),null,"fixed contract"));var impact=impactService().preview(admin,store,r.id(),"2026-12");assertThat(impact.afterNet()).isEqualTo("2400.00");assertThat(impact.beforeNet()).isNull();assertThat(impact.warnings()).contains("FIXED_FUTURE_CONTRACT_ASSUMPTION");}
 @Test void assumptionsAreAppliedBeforeFixedFilteringAndAutomaticGeneration(){completed();var p=configs.findProfile(tenant,profile).orElseThrow();var fixed=new Rule("monthly","3100.00","8","44",false,"1.5",List.of(),new Generation("fixed",List.of()));var assumed=new PayProfile(p.id(),p.companyId(),p.employeeId(),p.employeeName(),p.effectiveFrom(),p.templateId(),p.templateVersion(),fixed,p.cpf(),p.version()+1);var proposed=new ProfileWrite(p.version(),company,employee,p.effectiveFrom(),p.templateId(),fixed,p.cpf());var request=changes().save(admin,store,UUID.randomUUID(),new com.rpb.reservation.workforce.payroll.governance.PayChangeDtos.Write(0L,company,employee,p.effectiveFrom(),null,proposed,List.of(),null,"fixed estimate"));var captured=sources.captureAssuming(tenant,company,YearMonth.of(2026,10),List.of(),new com.rpb.reservation.workforce.payroll.PayrollSources.Assumptions(request.id(),request.revision(),request.hash(),List.of(request.content().profile()),Map.of()));var line=captured.lines().getFirst();assertThat(line.profile().rule().rate()).isEqualTo("3100.00");assertThat(line.sources()).isEmpty();assertThat(line.input().generation()).isEqualTo("fixed");assertThat(configs.findProfile(tenant,profile).orElseThrow()).isEqualTo(p);assertThat(jdbc.queryForObject("select count(*) from workforce_pay_batches where tenant_id=?",Integer.class,tenant)).isZero();}
}
